type Incompatibility = dyn Fn(&AcpLaunch<'_>) -> Option<String> + Send + Sync;
type NativeSession = dyn Fn(&AcpLaunch<'_>, &str) -> bool + Send + Sync;

/// A session setting the agent has to hold before a run's prompt, named the
