    #[serde(skip_serializing_if = "Option::is_none")]
    pub acp_session_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub restore: Option<AcpRestore>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub agent: Option<AcpAgentIdentity>,
    pub decided_at: String,
}

